<?php
namespace App\Events;
use Illuminate\Broadcasting\PrivateChannel;use Illuminate\Contracts\Broadcasting\ShouldBroadcastNow;use Illuminate\Foundation\Events\Dispatchable;
/** Provides chat typing changed behavior within the WorkIntel application. */ class ChatTypingChanged implements ShouldBroadcastNow{use Dispatchable;/** Initializes the class with its required dependencies and state. */ public function __construct(public int $workspaceId,public int $conversationId,public int $memberId,public bool $typing){}/** Handles the broadcast on operation for the current WorkIntel workflow. */ public function broadcastOn():array{return[new PrivateChannel("workspace.{$this->workspaceId}.chat.{$this->conversationId}")];}/** Handles the broadcast as operation for the current WorkIntel workflow. */ public function broadcastAs():string{return'chat.typing';}/** Handles the broadcast with operation for the current WorkIntel workflow. */ public function broadcastWith():array{return['conversation_id'=>$this->conversationId,'member_id'=>$this->memberId,'typing'=>$this->typing];}}
